function mpConfig():array{return loadDoc('integrations');}
function mpEnabled():bool{$i=mpConfig();return !empty($i['mp_enabled'])&&!empty($i['mp_access_token'])&&!empty($i['mp_webhook_secret']);}
function mpRequest(string $path,?array $data=null,string $key=''):array{$i=mpConfig();if(empty($i['mp_access_token']))fail('Mercado Pago ainda não configurado.',503);$ch=curl_init('https://api.mercadopago.com'.$path);$headers=['Authorization: Bearer '.$i['mp_access_token'],'Content-Type: application/json'];if($key)$headers[]='X-Idempotency-Key: '.$key;curl_setopt_array($ch,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_TIMEOUT=>20,CURLOPT_HTTPHEADER=>$headers,CURLOPT_SSL_VERIFYPEER=>true]);if($data!==null)curl_setopt_array($ch,[CURLOPT_POST=>true,CURLOPT_POSTFIELDS=>json_encode($data)]);$raw=curl_exec($ch);$code=curl_getinfo($ch,CURLINFO_HTTP_CODE);$curlError=curl_errno($ch);curl_close($ch);if(!$raw||$code<200||$code>=300){$error=json_decode($raw?:'{}',true);$causes=array_map(fn($cause)=>preg_replace('/[^a-zA-Z0-9_-]/','',(string)($cause['code']??'')),$error['cause']??[]);error_log('BRYXA MercadoPago HTTP '.(int)$code.' curl '.(int)$curlError.' codes '.implode(',',$causes).' order '.preg_replace('/[^a-zA-Z0-9_-]/','',$key));$message=in_array($code,[401,403])?'O Mercado Pago não autorizou a operação. A loja precisa conferir as credenciais e permissões.':($code===400||$code===422?'O Mercado Pago recusou os dados desta tentativa. Confira os dados ou escolha outra forma de pagamento.':'Não foi possível confirmar a resposta do Mercado Pago. Confira o acompanhamento antes de tentar novamente.');fail($message.($causes?' Referência: '.implode(',',$causes).'.':''),502);}$result=json_decode($raw,true);if(!is_array($result))fail('Resposta de pagamento inválida.',502);return $result;}
function paymentUpdate(array $payment):array{global $db;$id=(string)($payment['external_reference']??'');$db->beginTransaction();$q=$db->prepare('SELECT data FROM orders WHERE id=?');$q->execute([$id]);$o=json_decode($q->fetchColumn()?:'null',true);if(!$o){$db->rollBack();fail('Pedido de pagamento não encontrado.',404);}if(abs((float)($payment['transaction_amount']??0)-$o['total'])>0.001||($payment['currency_id']??'')!=='BRL'){$db->rollBack();fail('Pagamento não corresponde ao pedido.',409);}if(isset($o['payment_id'])&&(string)$o['payment_id']!==(string)$payment['id']){if(($o['checkout_mode']??'')!=='pro'){$db->rollBack();fail('Pagamento não corresponde ao pedido.',409);}if($o['payment_status']==='approved'||($o['payment_status']==='pending'&&in_array($payment['status'],['rejected','cancelled']))){$db->rollBack();return $o;}}if((bool)($payment['live_mode']??false)===(bool)($o['sandbox']??true)){$db->rollBack();fail('Ambiente de pagamento não corresponde ao pedido.',409);}$status=$payment['status'];$previous=$o['payment_status'];$o['payment_id']=(string)$payment['id'];$o['payment_status']=$status;if($status==='approved'&&$previous!=='approved'){$o['timeline'][]=['status'=>'Pagamento aprovado','time'=>date('c'),'source'=>'Mercado Pago'];$o['status']='Recebido';orderEmail($o,'payment_approved',$id.':payment-approved');}if(($o['checkout_mode']??'')!=='pro'&&in_array($status,['rejected','cancelled'])&&!empty($o['reserved_stock'])){$products=loadDoc('products');foreach($o['items'] as $item)foreach($products as &$p)if($p['id']===$item['id'])$p['stock'][$item['size']]=($p['stock'][$item['size']]??0)+$item['quantity'];unset($p);saveDoc('products',$products);$o['reserved_stock']=false;}if($previous!==$status&&in_array($status,['pending','rejected','refunded']))orderEmail($o,['pending'=>'payment_pending','rejected'=>'payment_rejected','refunded'=>'refunded'][$status],$id.':payment:'.$status);saveOrder($o);$db->commit();return $o;}
if($action==='mp-settings'&&$method==='POST'){auth();$b=body();$i=loadDoc('integrations');$i['mp_public_key']=textValue($b['mp_public_key']??'',300);foreach(['mp_access_token','mp_webhook_secret'] as $field){if(!empty($b['clear_'.$field]))$i[$field]='';elseif(!empty($b[$field]))$i[$field]=textValue($b[$field],6000);}$i['mp_sandbox']=!empty($b['mp_sandbox']);$i['mp_enabled']=!empty($b['mp_enabled']);if($i['mp_enabled']&&(empty($i['mp_access_token'])||empty($i['mp_webhook_secret'])))fail('Informe Access Token e segredo do webhook antes de ativar.');if($i['mp_enabled']&&(!$i['mp_sandbox']||PHP_SAPI!=='cli-server')&&empty($_SERVER['HTTPS']))fail('O pagamento precisa de HTTPS.');saveDoc('integrations',$i);reply(['ok'=>true]);}
if($action==='mp-config'&&$method==='GET'){reply(['enabled'=>mpEnabled(),'mode'=>'pro','public_key'=>mpEnabled()?(mpConfig()['mp_public_key']??''):'','sandbox'=>mpConfig()['mp_sandbox']??true,'demo'=>demoMode()]);}
if($action==='checkout-prepare'&&$method==='POST'){requestLimit('checkout',10);if(!mpEnabled()||demoMode())fail('Pagamento real indisponível nesta prévia.',503);$b=body();$c=$b['customer']??[];$clean=[];foreach(['name','email','postal_code','street','number','complement','neighborhood','city','state'] as $f)$clean[$f]=textValue($c[$f]??'',254);foreach(['name','street','number','neighborhood','city'] as $f)if(!$clean[$f])fail('Confira os dados de entrega.');if(!filter_var($clean['email'],FILTER_VALIDATE_EMAIL)||!preg_match('/^[A-Z]{2}$/',$clean['state']))fail('Confira e-mail e estado.');$clean['postal_code']=preg_replace('/\D/','',$clean['postal_code']);$items=$b['items']??[];$quote=$_SESSION['shipping_quote']??null;if(!$quote||$quote['expires']<time()||$quote['cep']!==$clean['postal_code'])fail('Calcule o frete novamente.');$signature=array_map(fn($x)=>['id'=>$x['id']??'','quantity'=>$x['quantity']??0],$items);if(json_encode($signature)!==$quote['items'])fail('A sacola mudou. Recalcule o frete.');$shipping=null;foreach($quote['quotes'] as $q)if((string)$q['id']===(string)($b['shipping_id']??''))$shipping=$q;if(!$shipping)fail('Escolha o frete.');if($shipping['id']==='pickup'&&empty(mpConfig()['pickup_enabled']))fail('Retirada desativada. Recalcule o frete.');$catalog=array_column(loadDoc('products'),null,'id');$lines=[];$cents=0;$counts=[];foreach($items as $item){$p=$catalog[$item['id']??'']??null;$size=textValue($item['size']??'',20);$qty=$item['quantity']??0;if(!$p||!$p['active']||!is_int($qty)||$qty<1||$qty>100)fail('Peça inválida.');$key=$p['id'].':'.$size;$counts[$key]=($counts[$key]??0)+$qty;if(($p['stock'][$size]??0)<$counts[$key])fail('Estoque indisponível.');$lines[]=['id'=>$p['id'],'name'=>$p['name'],'price'=>$p['price'],'size'=>$size,'quantity'=>$qty,'custom'=>$item['custom']??null];$cents+=(int)round($p['price']*100)*$qty;}if(!$lines)fail('Sacola vazia.');$pricing=cartPricing($items,textValue($b['coupon']??'',40));if(($quote['pricing']??'')!==hash('sha256',json_encode($pricing)))fail('Os valores ou a promoção mudaram. Recalcule o frete.');foreach($lines as $index=>&$line){$line['nicks']=cleanItemNicks($items[$index]);$line['nick']=cleanItemNick($items[$index]);if(!empty($line['custom']))$line['price']=round($line['price']+(loadDoc('settings')['personalization_price']??0),2);}unset($line);$id='BRYXA-'.strtoupper(bin2hex(random_bytes(6)));$draft=['id'=>$id,'customer'=>$clean,'items'=>$lines,'shipping'=>$shipping,'subtotal'=>$pricing['subtotal'],'discount'=>$pricing['discount'],'gift'=>$pricing['gift'],'total'=>round($pricing['net']+$shipping['price'],2),'payment_status'=>'not_created','status'=>'Aguardando pagamento','sandbox'=>mpConfig()['mp_sandbox']??true,'timeline'=>[['status'=>'Pedido recebido','time'=>date('c'),'source'=>'checkout']],'created'=>date('c')];$db->prepare('INSERT INTO checkout_drafts VALUES(?,?,?,?)')->execute([$id,json_encode($draft),session_id(),time()+1800]);reply(['draft_id'=>$id,'amount'=>$draft['total'],'sandbox'=>$draft['sandbox']]);}
if($action==='mp-pay')fail('Checkout atualizado. Recarregue a página para pagar pelo Mercado Pago.',410);
require __DIR__.'/checkout-pro.php';
if($action==='mp-webhook'&&$method==='POST'){$i=mpConfig();if(empty($i['mp_webhook_secret']))fail('Webhook não configurado.',503);$id=(string)($_GET['data_id']??'');if(!preg_match('/^[0-9]+$/',$id))fail('Identificador inválido.',400);$signature=$_SERVER['HTTP_X_SIGNATURE']??'';$parts=[];foreach(explode(',',$signature) as $part){$kv=explode('=',$part,2);if(count($kv)===2)$parts[trim($kv[0])]=trim($kv[1]);}$ts=$parts['ts']??'';$request=$_SERVER['HTTP_X_REQUEST_ID']??'';if(!ctype_digit($ts)||!$request||empty($parts['v1']))fail('Assinatura inválida.',401);$manifest='id:'.$id.';request-id:'.$request.';ts:'.$ts.';';if(!hash_equals(hash_hmac('sha256',$manifest,$i['mp_webhook_secret']),$parts['v1']))fail('Assinatura inválida.',401);$payment=mpRequest('/v1/payments/'.$id);paymentUpdate($payment);reply(['ok'=>true]);}
